This continues the Node/TypeScript stack and uses the HaveIBeenPwned (HIBP) Pwned Passwords range API. Only the first 5 characters of the password's SHA-1 hash leave your server, and the match happens locally.

```ts
// breachCheck.ts
import { createHash } from "node:crypto";

const HIBP_RANGE_URL = "https://api.pwnedpasswords.com/range/";
const TIMEOUT_MS = 1500;
const CACHE_TTL_MS = 60 * 60 * 1000;
const CACHE_MAX_ENTRIES = 5000;

export type BreachResult =
  | { status: "ok"; breached: boolean; count: number }
  | { status: "unavailable" };

// Cache by 5-char prefix. The response is the same for everyone and contains no
// secrets, so it's safe to share across users. Swap for Redis if you run multiple instances.
const prefixCache = new Map<string, { expires: number; body: string }>();

async function fetchRange(prefix: string): Promise<string> {
  const hit = prefixCache.get(prefix);
  if (hit && hit.expires > Date.now()) return hit.body;

  const res = await fetch(HIBP_RANGE_URL + prefix, {
    headers: {
      "Add-Padding": "true", // pads responses so size doesn't leak how many matches exist
      "User-Agent": "YourApp-password-check",
    },
    signal: AbortSignal.timeout(TIMEOUT_MS),
  });
  if (!res.ok) throw new Error(`HIBP responded ${res.status}`);
  const body = await res.text();

  if (prefixCache.size >= CACHE_MAX_ENTRIES) {
    prefixCache.delete(prefixCache.keys().next().value!); // evict oldest
  }
  prefixCache.set(prefix, { expires: Date.now() + CACHE_TTL_MS, body });
  return body;
}

export async function checkPasswordBreached(password: string): Promise<BreachResult> {
  // SHA-1 here is a lookup key for the HIBP API, not password storage.
  const sha1 = createHash("sha1").update(password, "utf8").digest("hex").toUpperCase();
  const prefix = sha1.slice(0, 5);
  const suffix = sha1.slice(5);

  try {
    const body = await fetchRange(prefix);
    for (const line of body.split("\n")) {
      const [candidate, countStr] = line.trim().split(":");
      if (candidate === suffix) {
        const count = parseInt(countStr, 10) || 0;
        // Padding entries have count 0 and are not real matches.
        if (count > 0) return { status: "ok", breached: true, count };
      }
    }
    return { status: "ok", breached: false, count: 0 };
  } catch {
    return { status: "unavailable" }; // timeout, network error, 429, 5xx
  }
}
```

