```ts
declare function markPasswordBreached(userId: string): Promise<void>; // sets password_breach_flagged_at
declare function startForcedPasswordReset(userId: string): Promise<void>;

// After verifying the password, before issuing a full session:
const breach = await checkPasswordBreached(submittedPassword);
if (breach.status === "ok" && breach.breached) {
  await markPasswordBreached(user.id);
  // Don't issue a normal session. Require MFA/email verification, then a password change.
  await startForcedPasswordReset(user.id);
  return res.status(403).json({ error: "password_reset_required", reason: "found_in_breach" });
}
if (breach.status === "unavailable") {
  logMetric("breach_check_unavailable", { where: "login" }); // never block login on HIBP downtime
}
