```ts
import { createHash } from "node:crypto";

declare const db: any;

// ---- Providers: return how many times a SHA-1 appears in breach data ----
interface BreachProvider {
  count(sha1Upper: string): Promise<number>;
}

// Remote: only the first 5 hex chars of the hash leave your system.
export const hibpProvider: BreachProvider = {
  async count(sha1) {
    const prefix = sha1.slice(0, 5);
    const suffix = sha1.slice(5);
    const res = await fetch(`https://api.pwnedpasswords.com/range/${prefix}`, {
      headers: { "Add-Padding": "true", "User-Agent": "YourApp-breach-check" },
      signal: AbortSignal.timeout(2000),
    });
    if (!res.ok) throw new Error(`HIBP responded ${res.status}`);

    for (const line of (await res.text()).split("\n")) {
      const [s, c] = line.trim().split(":");
      if (s === suffix) return parseInt(c, 10); // padded fake rows have count 0
    }
    return 0;
  },
};

// Local: load the HIBP offline hash list into a table first
//   CREATE TABLE breached_passwords (sha1 CHAR(40) PRIMARY KEY, count INT NOT NULL);
export const localProvider: BreachProvider = {
  async count(sha1) {
    const { rows } = await db.query(
      `SELECT count FROM breached_passwords WHERE sha1 = $1`,
      [sha1]
    );
    return rows[0]?.count ?? 0;
  },
};

