    const count = await provider.count(sha1);
    return count > 0 ? { status: "breached", count } : { status: "clean" };
  } catch (err) {
    // Log the error, never the password or hash
    console.error("breach check failed:", (err as Error).message);
    return { status: "unavailable" };
  }
