Because deep sleep resets the CPU, this isn't a true loop. `app_main` runs once per wake and ends by going back to sleep, and the "loop" is the repeating cycle of wake, run, sleep. This sketch uses the timer and buffer functions from earlier.

```c
#include "esp_sleep.h"
#include "esp_timer.h"
#include "esp_log.h"

#define SAMPLE_INTERVAL_S   300     // wake every 5 min
#define TX_BATCH_SIZE       12      // transmit once 12 readings are buffered
#define LOW_BATT_MV         3300    // below this, stop using the radio
#define MAX_BACKOFF_WAKES   12      // cap on skipped transmit opportunities

static const char *TAG = "cycle";

/* Survives deep sleep, like the reading buffer */
RTC_DATA_ATTR static uint8_t s_consecutive_tx_failures;
RTC_DATA_ATTR static uint8_t s_wakes_until_retry;

/* Sleep for whatever is left of the interval, so the period stays ~constant
 * even when transmit cycles keep the device awake longer. */
static void sleep_until_next_cycle(void)
{
    uint32_t awake_s = (uint32_t)((esp_timer_get_time() + 500000) / 1000000);
    uint32_t sleep_s = (awake_s < SAMPLE_INTERVAL_S) ? SAMPLE_INTERVAL_S - awake_s : 1;

    if (set_wake_timer(sleep_s) == ESP_OK) {
        esp_deep_sleep_start();            // does not return
    }
    esp_restart();                         // timer arm failed: don't hang awake
}

/* Wake the radio, drain the buffer in batches, sleep the radio.
 * Returns true if everything buffered was delivered. */
static bool try_transmit(void)
{
    reading_t batch[TX_BATCH_SIZE];
    bool ok = true;

    radio_wake();
    while (reading_buffer_count() > 0) {
        size_t n = reading_buffer_peek(batch, TX_BATCH_SIZE);
        if (!radio_send(batch, n)) {       // must have its own timeout
            ok = false;
            break;
        }
        reading_buffer_discard(n);         // only after confirmed delivery
    }
    radio_sleep();
    return ok;
}

void app_main(void)
{
    reading_buffer_init();

    esp_sleep_wakeup_cause_t cause = esp_sleep_get_wakeup_cause();
    if (cause == ESP_SLEEP_WAKEUP_UNDEFINED) {
        ESP_LOGI(TAG, "cold boot");        // first power-up or reset: do one-time setup here
    }

    /* 1. Sample */
    sensors_power_on();
    reading_t r = read_sensors();
    sensors_power_off();
    reading_buffer_add(&r);

    /* 2. Decide whether to transmit */
    bool batt_ok = (r.battery_mv >= LOW_BATT_MV);
    bool due     = (reading_buffer_count() >= TX_BATCH_SIZE);

    if (due && batt_ok) {
        if (s_wakes_until_retry > 0) {
            s_wakes_until_retry--;         // backing off after failures
        } else if (try_transmit()) {
            s_consecutive_tx_failures = 0;
        } else {
            if (s_consecutive_tx_failures < MAX_BACKOFF_WAKES) {
                s_consecutive_tx_failures++;
            }
            s_wakes_until_retry = s_consecutive_tx_failures;  // wait longer each time
        }
    }

    /* 3. Sleep */
    sleep_until_next_cycle();
}
```

Timeline of one cycle:

```
wake -> sample -> buffer -> [transmit if 12+ buffered] -> deep sleep (~5 min)
 ~100s of ms      ms           seconds, 1 in 12 wakes        µA-level
```

Design notes:

- **Failed sends use linear backoff.** If the gateway is down or out of range, retrying every 5 minutes can drain the battery faster than anything else in the design, because the radio is your biggest consumer. After each failure the device skips one more wake before retrying, up to a cap. Readings keep accumulating in the buffer meanwhile, so size it for the worst outage you want to survive.
- **Bound every wait.** `radio_send` needs a hard timeout, and I'd also enable the task watchdog. A radio that hangs while awake will empty the battery quickly.
